class InvalidBroadcastSelected(Exception):
    """
    Raised when selected broadcast is neither CMAS nor ETWS.
    """
    pass


class LoginIntoCBCFailed(Exception):
    """
    Raised when login attempt into CBC fails.
    """
    pass


class CbcInstanceAlreadyRunning(Exception):
    """
    Raised when cbc script is already running.
    """
    pass
